using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1️⃣  Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip to prove it works:
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2️⃣  Probe without throwing — TryGetTypeInfo returns false if unavailable.
//     Use an options instance with NO resolver so the type won't be found.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// Make it "locked" by performing a serialization, then swap resolver to null-like.
// Simpler: just use an options with no resolver at all:
var noResolver = new JsonSerializerOptions { TypeInfoResolver = null! };

if (noResolver.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata NOT available for Person (no exception thrown).");
}

// Also show a successful TryGetTypeInfo call:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"TryGetTypeInfo succeeded: {info2!.Type.Name}");
}

public record Person(string Name, int Age);

